-- CAB-0006: scoped editorial import. Deploy portrait/logo assets before applying.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='pkr' and type='party') then raise exception 'CAB-0006: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='pbb' and type='party') then raise exception 'CAB-0006: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('chang-lih-kang','nancy-shukri') and (type <> 'politician' or owner_id is not null)) then raise exception 'CAB-0006: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('tanjong malim','santubong') and slug not in ('chang-lih-kang','nancy-shukri')) then raise exception 'CAB-0006: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'CAB-0006:%' and (m.source_type <> 'editorial' or e.slug not in ('chang-lih-kang','nancy-shukri') or m.import_key not like 'CAB-0006:' || e.slug || ':%')) then raise exception 'CAB-0006: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician', parent.id,'chang-lih-kang','Chang Lih Kang','government','Minister of Science, Technology and Innovation','Tanjong Malim','Perak','Chang Lih Kang is Minister of Science, Technology and Innovation. He represents Tanjong Malim, Perak, in the Dewan Rakyat. He is a member of Parti Keadilan Rakyat (PKR).','https://www.mosti.gov.my/','/portraits/chang-lih-kang.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P077.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Prime Minister’s Office · Cabinet", "url": "https://www.pmo.gov.my/en/cabinet/"}, {"label": "Parliament · Tanjong Malim", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4116"}, {"label": "PKR · representatives", "url": "https://keadilanrakyat.org/wakil-rakyat/"}]'::jsonb from public.entities parent where parent.slug='pkr' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician', parent.id,'nancy-shukri','Nancy Shukri','government','Minister of Women, Family and Community Development','Santubong','Sarawak','Nancy Shukri is Minister of Women, Family and Community Development. She represents Santubong, Sarawak, in the Dewan Rakyat. She is a member of Parti Pesaka Bumiputera Bersatu (PBB).','https://www.kpwkm.gov.my/','/portraits/nancy-shukri.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/santubong.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Prime Minister’s Office · Cabinet", "url": "https://www.pmo.gov.my/en/cabinet/"}, {"label": "Parliament · Santubong", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4232"}, {"label": "PBB · Nancy Shukri (22 Oct 2026)", "url": "https://www.bernama.com/en/politics/news.php?id=2624300"}]'::jsonb from public.entities parent where parent.slug='pbb' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('chang-lih-kang','nancy-shukri') and type='politician' and owner_id is null) <> 2 then raise exception 'CAB-0006: concurrent ownership or identity change'; end if; end $$;

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'CAB-0006:chang-lih-kang:dstin-gerd-floor-2030','Raise R&D spending to at least 2.5% of GDP by 2030 under DSTIN','Economy','in_progress',null,'2030-12-31','2025-07-17','https://www.mosti.gov.my/wp-content/uploads/2025/07/17072025.1080073394.pdf','2025-07-17','https://www.mosti.gov.my/wp-content/uploads/2025/07/17072025.1080073394.pdf','MOSTI’s release, quoting Chang on strengthening research, commits to the DSTIN 2021–2030 spending floor of at least 2.5% of GDP by 2030.','The release lists active research-funding and commercialisation initiatives and a 2022 GERD baseline of 1.01%. It separately mentions a broader 3.5% MADANI ambition. This record tracks the explicitly dated DSTIN floor; neither figure is a completion score or a current spending result.','2026-11-09','editorial',false from public.entities e where e.slug='chang-lih-kang' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

insert into public.milestones (entity_id,import_key,title,category,status,progress,target_date,promise_date,promise_url,evidence_date,evidence_url,description,progress_note,progress_checked_at,source_type,is_sample) select e.id,'CAB-0006:nancy-shukri:mammograms-38000-2027','Support mammogram screening for 38,000 women under Budget 2027','Social welfare',null,null,'2027-12-31','2026-10-21','https://www.bernama.com/en/general/news.php?id=2623525',null,null,'Nancy said the Budget 2027 mammogram subsidy allocation was expected to benefit 38,000 women.','The report establishes the 2027 target and allocation, not delivery to those 38,000 women. Cumulative screenings since 2007 are not this target’s outcome. Completion and status remain unknown.','2026-11-09','editorial',false from public.entities e where e.slug='nancy-shukri' on conflict (import_key) do update set title=excluded.title,category=excluded.category,status=excluded.status,progress=excluded.progress,target_date=excluded.target_date,promise_date=excluded.promise_date,promise_url=excluded.promise_url,evidence_date=excluded.evidence_date,evidence_url=excluded.evidence_url,description=excluded.description,progress_note=excluded.progress_note,progress_checked_at=excluded.progress_checked_at,source_type=excluded.source_type,is_sample=excluded.is_sample where public.milestones.entity_id=excluded.entity_id and public.milestones.source_type='editorial' and ROW(public.milestones.title,public.milestones.category,public.milestones.status,public.milestones.progress,public.milestones.target_date,public.milestones.promise_date,public.milestones.promise_url,public.milestones.evidence_date,public.milestones.evidence_url,public.milestones.description,public.milestones.progress_note,public.milestones.progress_checked_at,public.milestones.source_type,public.milestones.is_sample) IS DISTINCT FROM ROW(excluded.title,excluded.category,excluded.status,excluded.progress,excluded.target_date,excluded.promise_date,excluded.promise_url,excluded.evidence_date,excluded.evidence_url,excluded.description,excluded.progress_note,excluded.progress_checked_at,excluded.source_type,excluded.is_sample);

commit;
